import 'dart:ffi';
import 'dart:isolate';
import 'dart:typed_data';

import 'package:ffi/ffi.dart';

import 'image_lab_bindings.g.dart';

// ---------------------------------------------------------------------------
// What this file shows: calling C from Dart with dart:ffi.
//
// image_lab_bindings.g.dart is GENERATED by ffigen from image_lab.h. It gives us
// typed Dart functions (box_blur_rgba, filter_rgba). This file is the
// hand-written layer on top that makes them pleasant and safe to use.
//
// Three FFI rules that explain the shape of this code:
//   1. Native memory is NOT managed by Dart's garbage collector. Everything we
//      malloc, we must free (hence try/finally everywhere).
//   2. An FFI call is a plain synchronous function call. While it runs, the
//      calling isolate is blocked. On the UI isolate that freezes the screen.
//   3. C has no exceptions. Errors come back as return codes (0 = OK).
// ---------------------------------------------------------------------------

/// Loads the compiled C library. CMake (android/app/src/main/cpp/CMakeLists.txt)
/// builds it as libimage_lab.so and Gradle packages it into the APK.
ImageLabBindings _open() =>
    ImageLabBindings(DynamicLibrary.open('libimage_lab.so'));

class NativeImageLab {
  /// Throws if the .so can't be loaded (for example an ABI the NDK didn't build).
  NativeImageLab() : _lib = _open();
  final ImageLabBindings _lib;

  /// Simplest possible FFI call: C returns a `char*`. It points at a static
  /// string inside the library, so Dart must NOT free it.
  String version() => _lib.image_lab_version().cast<Utf8>().toDartString();

  /// Blurs [rgba] (4 bytes per pixel) in C and returns the result.
  ///
  /// Runs on the CALLING isolate. Call it from the UI isolate and the UI
  /// freezes until C finishes. Compare with [blurInBackground].
  Uint8List blur(Uint8List rgba, int w, int h, int radius) {
    final len = rgba.length;

    // C can't read a Dart Uint8List directly (the GC may move it), so we copy
    // the pixels into native memory that C can safely point at.
    final src = malloc<Uint8>(len);
    final dst = malloc<Uint8>(len);
    try {
      src.asTypedList(len).setAll(0, rgba); // copy Dart -> native

      final code = _lib.box_blur_rgba(src, dst, w, h, radius);
      if (code != 0) throw StateError('box_blur_rgba failed with code $code');

      // Copy native -> Dart. fromList makes an independent copy, which matters
      // because we free `dst` right below.
      return Uint8List.fromList(dst.asTypedList(len));
    } finally {
      malloc.free(src); // never forget: the GC will not do this for us
      malloc.free(dst);
    }
  }

  /// Same blur, but on a background isolate so the screen stays smooth.
  ///
  /// Isolates can't share Dart objects, and a `Pointer` can't be sent between
  /// them. But native memory belongs to the whole process, so we send the plain
  /// integer ADDRESSES and rebuild the pointers on the other side.
  static Future<Uint8List> blurInBackground(
      Uint8List rgba, int w, int h, int radius) async {
    final len = rgba.length;
    final src = malloc<Uint8>(len);
    final dst = malloc<Uint8>(len);
    try {
      src.asTypedList(len).setAll(0, rgba);
      final srcAddr = src.address; // Pointer -> int
      final dstAddr = dst.address;

      // Isolate.run starts a worker, runs the closure there, returns the result.
      // The closure may only capture plain values (ints here). Capturing `this`
      // would try to send the whole object, including the DynamicLibrary, and
      // crash with "Illegal argument in isolate message".
      final code =
      await Isolate.run(() => _blurAt(srcAddr, dstAddr, w, h, radius));
      if (code != 0) throw StateError('box_blur_rgba failed with code $code');
      return Uint8List.fromList(dst.asTypedList(len));
    } finally {
      malloc.free(src);
      malloc.free(dst);
    }
  }

  /// Applies one of the photo filters in C on a background isolate.
  /// [filter] must match the ids in image_lab.c: 0 blur, 1 pixelate,
  /// 2 grayscale, 3 sepia. [amount] is blur radius or pixelate block size.
  ///
  /// This is what the Photo Filters screen uses. It follows the same recipe as
  /// [blurInBackground]: copy in, run in a worker, copy out, free.
  static Future<Uint8List> filterInBackground(
      Uint8List rgba, int w, int h, int filter, int amount) async {
    final len = rgba.length;
    final src = malloc<Uint8>(len);
    final dst = malloc<Uint8>(len);
    try {
      src.asTypedList(len).setAll(0, rgba);
      final srcAddr = src.address;
      final dstAddr = dst.address;
      final code = await Isolate.run(
              () => _filterAt(srcAddr, dstAddr, w, h, filter, amount));
      if (code != 0) throw StateError('filter_rgba failed with code $code');
      return Uint8List.fromList(dst.asTypedList(len));
    } finally {
      malloc.free(src);
      malloc.free(dst);
    }
  }
}

// These two are top-level functions on purpose: a closure inside the class
// could implicitly capture `this`. Here the only inputs are plain ints.
// Each worker isolate opens the library itself: a DynamicLibrary can't be
// passed in, but opening the same .so again is cheap.

int _blurAt(int srcAddr, int dstAddr, int w, int h, int radius) {
  final lib = _open();
  return lib.box_blur_rgba(
    Pointer<Uint8>.fromAddress(srcAddr), // int -> Pointer again
    Pointer<Uint8>.fromAddress(dstAddr),
    w,
    h,
    radius,
  );
}

int _filterAt(int srcAddr, int dstAddr, int w, int h, int filter, int amount) {
  final lib = _open();
  return lib.filter_rgba(
    Pointer<Uint8>.fromAddress(srcAddr),
    Pointer<Uint8>.fromAddress(dstAddr),
    w,
    h,
    filter,
    amount,
  );
}